      "action_name": "auto-setToleranceBreakEnabled",
      "description": "设置容差中断开关。",
      "description_en": "Enable or disable tolerance-based stopping."
    },
    {
      "action_name": "auto-setAbsoluteTolerance",
      "description": "设置绝对容差。",
      "description_en": "Set the absolute tolerance."
    },
    {
      "action_name": "auto-setRelativeTolerance",
      "description": "设置相对容差。",
      "description_en": "Set the relative tolerance."
    },
    {
      "action_name": "auto-setChargeBreakEnabled",
      "description": "设置电荷中断开关。",
      "description_en": "Enable or disable charge-based stopping."
    },
    {
      "action_name": "auto-setMaximumCharge",
      "description": "设置最大电荷。",
      "description_en": "Set the maximum charge."
    },
    {
      "action_name": "auto-setMinimumCharge",
      "description": "设置最小电荷。",
      "description_en": "Set the minimum charge."
    },
    {
      "action_name": "auto-getTemperature",
      "description": "读取外接热电偶温度。",
      "description_en": "Read temperature from the connected thermocouple."
    },
    {
      "action_name": "auto-setStepSize",
      "description": "设置阶梯步长。",
      "description_en": "Set the staircase step size."
    },
    {
      "action_name": "auto-measureRampValueInTime",
      "description": "在指定时间内扫描到目标值。",
      "description_en": "Run a ramp to a target value within a specified time."
    },
    {
      "action_name": "auto-measureRampValueInScanRate",
      "description": "以指定扫描速率扫描到目标值。",
      "description_en": "Run a ramp to a target value at a specified scan rate."
    },
    {
      "action_name": "auto-measureRampScanRateForTime",
      "description": "以指定扫描速率运行指定时间。",
      "description_en": "Run at a specified scan rate for a specified time."
    },
    {
      "action_name": "auto-measurePolarization",
      "description": "执行恒电位或恒电流极化测量。",
      "description_en": "Run potentiostatic or galvanostatic polarization."
    },
    {
      "action_name": "auto-measureOCVScan",
      "description": "执行开路电位随时间测量。",
      "description_en": "Measure open-circuit voltage over time."
    },
    {
      "action_name": "auto-measureOCV",
      "description": "测量开路电位并更新参考。",
      "description_en": "Measure open-circuit voltage and update the reference."
    },
    {
      "action_name": "auto-measureIEStairs",
      "description": "执行电压或电流阶梯测量。",
      "description_en": "Run a voltage or current staircase measurement."
    },
    {
      "action_name": "auto-checkConnectionPolarity",
      "description": "检查接线极性是否正确。",
      "description_en": "Check whether the connection polarity is correct."
    },
    {
      "action_name": "auto-measureCharge",
      "description": "以恒流方式对样品充电直到达到停止条件。",
      "description_en": "Charge a sample galvanostatically until a stop condition is reached."
    },
    {
      "action_name": "auto-measureDischarge",
      "description": "以恒流方式对样品放电直到达到停止条件。",
      "description_en": "Discharge a sample galvanostatically until a stop condition is reached."
    },
    {
      "action_name": "auto-measureProfile",
      "description": "按序输出极化或斜坡轮廓。",
      "description_en": "Output a sequence profile of polarizations or ramps."
    },
    {
      "action_name": "auto-measurePITT",
      "description": "执行 PITT 间歇滴定测量。",
      "description_en": "Run a PITT intermittent titration measurement."
    },
    {
      "action_name": "auto-measureGITT",
      "description": "执行 GITT 间歇滴定测量。",
      "description_en": "Run a GITT intermittent titration measurement."
    }
  ],
  "tag_hints": [
    "potentiostat/galvanostat",
    "electrochemistry",
    "SCPI instrument control",
    "battery charge discharge",
    "open-circuit potential measurement",
    "PITT/GITT",
    "voltage current ramps",
    "thermocouple temperature input"
  ]
}

